select public.prepify_load_bank('Maths', 4, $j$[["The factorization of 15x²y as a product of its factors is:",["(15x)(y)","(5x)(3xy)","(5x²)(3xy)","(3x)(5y)"],"B",3,0,"5e7c63834f71"],["The factorization of a⁴ + a²b² + b⁴ is:",["(a² + ab)(a² − ab)","(a + b)²(a − b)²","(a² + b² + ab)(a² + b² − ab)","(a² + b²)²"],"C",3,0,"00f66339e161"],["a⁴ + 64b⁴ factorizes as:",["(a² + 8b² + 4ab)(a² + 8b² − 4ab)","(a² + 4b)(a² − 4b)","(a + 4b)²(a − 4b)²","(a² + 8b²)²"],"A",3,0,"488c42652fa4"],["Which of the following is the factored form of x⁴ + 4m⁴?",["(x² + 2m)²","(x + 2m)²(x − 2m)²","(x² − 2m²)²","(x² + 2m² + 2xm)(x² + 2m² − 2xm)"],"D",3,0,"6438c4451a73"],["The factored form of y² − 7y + 12 is:",["(y + 3)(y + 4)","(y − 6)(y − 2)","(y − 3)(y − 4)","(y − 12)(y + 1)"],"C",3,0,"ed68aeeddca9"],["The factored form of m² − 2m − 15 is:",["(m − 5)(m + 3)","(m + 5)(m − 3)","(m − 15)(m + 1)","(m + 15)(m − 1)"],"A",3,0,"990018dcbba7"],["The factored form of 3x² + 22x − 16 is:",["(x − 8)(3x + 2)","(x + 4)(3x − 4)","(3x + 8)(x − 2)","(x + 8)(3x − 2)"],"D",3,0,"79fd978d407a"],["The factored form of x² + x − 2 is:",["(x − 2)(x + 1)","(x + 2)(x − 1)","(x + 2)(x + 1)","(x − 2)(x − 1)"],"B",3,0,"2c1b851194c2"],["When factorizing (x² + 3x − 4)(x² + 3x + 5) + 8, substituting a = x² + 3x gives:",["(a + 4)(a + 5) + 8","(a + 4)(a − 5) + 8","(a − 4)(a + 5) + 8","(a − 4)(a − 5) + 8"],"C",3,0,"a366ab9bc34d"],["The factored form of (x² + 3x − 4)(x² + 3x + 5) + 8 is:",["(x² + 3x + 4)(x² + 3x − 3)","(x² + 3x − 4)(x² + 3x + 1)","(x² + 3x + 2)(x² + 3x − 1)","(x + 4)(x + 3)(x − 1)(x − 3)"],"A",3,0,"3c40f3e1159f"],["The identity a³ + 3a²b + 3ab² + b³ equals:",["a³ + b³","(a − b)³","(a + b)(a² − ab + b²)","(a + b)³"],"D",3,0,"a53e617e0922"],["The factored form of 27a³ + 1 + 27a² + 9a is:",["(3a − 1)³","(3a + 1)³","(3a + 1)(9a² − 3a + 1)","(3a)³ + 1"],"B",3,0,"4020eaadc9c4"],["The expression 8x³ − 60x² + 150x − 125 factorizes as:",["(2x + 5)³","(x − 5)³","(2x − 5)³","(4x − 5)³"],"C",3,0,"c331720d6298"],["a³ + b³ factorizes as:",["(a + b)(a² − ab + b²)","(a − b)(a² + ab + b²)","(a + b)(a² + ab + b²)","(a + b)(a − b)²"],"A",3,0,"651530c38047"],["The factored form of x³ + 27y³ is:",["(x + 27y)(x² − 3xy + y²)","(x − 3y)(x² + 3xy + 9y²)","(x + 3y)³","(x + 3y)(x² − 3xy + 9y²)"],"D",3,0,"f2e0a726115e"],["The factored form of 8a³ − 125b³ is:",["(2a + 5b)(4a² − 10ab + 25b²)","(2a − 5b)(4a² + 10ab + 25b²)","(2a − 5b)³","(2a − 5b)(4a² − 25b²)"],"B",3,0,"0f7ce9503ecc"],["The HCF of 18ab³c, 30a²b⁴c³, and 24b²c⁵ is:",["6ab³c³","18b²c","6b²c","6b³c"],"C",3,0,"f94df55cbac6"],["The HCF of two or more polynomials is the polynomial that:",["divides each of them exactly and is of highest degree","is divisible by each of them","is the product of all their factors","has the lowest degree among all factors"],"A",3,0,"4a2e4d55aebf"],["The HCF of x² − 49 and x² − 4x − 21 is:",["x² − 49","(x − 7)(x + 7)","x + 7","x − 7"],"D",3,0,"3476cd0b723e"],["When finding the HCF of monomials, the HCF of the variable part is determined by taking:",["the highest power of each variable","the lowest power of each common variable","the product of all powers","the sum of all powers"],"B",3,0,"9824922dbad8"],["The LCM of two polynomials P and Q with HCF H is given by:",["LCM = P × Q × H","LCM = H ÷ (P × Q)","LCM = (P × Q) ÷ H","LCM = (P + Q) ÷ H"],"C",3,0,"bccf07ed4bd2"],["The product of two polynomials P and Q equals:",["HCF × LCM","HCF + LCM","HCF ÷ LCM","LCM ÷ HCF"],"A",3,0,"bbfd0e0315e9"],["If HCF of two polynomials is x − 7 and their LCM is x³ − 10x² + 11x + 70, their product is:",["(x − 7) + (x³ − 10x² + 11x + 70)","(x − 7) ÷ (x³ − 10x² + 11x + 70)","Cannot be determined","(x − 7)(x³ − 10x² + 11x + 70)"],"D",3,0,"4693d0e55e89"],["An algebraic fraction P/Q is defined when:",["Q = 0 always","P and Q are polynomials and Q ≠ 0","P and Q are integers only","P and Q are constants"],"B",3,0,"44f925638ab7"],["To add algebraic fractions with different denominators, we first find their:",["HCF","Product","LCM","Difference"]