select public.prepify_load_bank('Maths', 5, $j$[["Which one is the standard form of a linear equation in one variable?",["ax² + b = 0","ax + b = 0","ax + by = 0","ax² + bx + c = 0"],"B",3,0,"596a1f0356f8"],["What is the exponent of the variable in a linear equation?",["0","1","2","-1"],"B",3,0,"40498be07b83"],["Which of the following is a linear equation in one variable?",["x² + 3 = 0","xy + 3 = 0","2x + 3 = 0","x² + 2x = 0"],"C",3,0,"abe040216f74"],["Two or more equations that have the same solution are called:",["Compound equations","Equivalent equations","Radical equations","Absolute equations"],"B",3,0,"1cba84b04bd1"],["What is the solution of 5x − 2 − x = 4 − 3x − 27?",["x = −3","x = −5","x = 5","x = 3"],"A",3,0,"b652175e4339"],["Solve for x: 0.5x = 6.3 − 0.2x",["x = 6","x = 7","x = 8","x = 9"],"D",3,0,"40a8d751c0e3"],["To clear fractions while solving a linear equation, all terms are multiplied by the:",["GCF of denominators","Product of denominators","LCM of denominators","Sum of denominators"],"C",3,0,"aeaede00854e"],["What is the solution of (x-2)/2 + (x+10)/9 = 5?",["x = 4","x = 6","x = 8","x = 10"],"C",3,0,"4835aa917b62"],["Which property of equality is applied when both sides of −2x = 2/5 are divided by −2 to solve for x?",["Addition property","Subtraction property","Division property","Multiplication property"],"C",3,0,"fd25be2d2ebe"],["An equation in which the variable appears under a radical sign is called a:",["Linear equation","Radical equation","Absolute value equation","Compound equation"],"B",3,0,"f47f1a8262a4"],["What is the solution set of √2x = 4?",["{2}","{4}","{8}","{16}"],"C",3,0,"5f96c3f073dd"],["What is the solution set of √(x-3)= 2?",["{1}","{5}","{7}","{9}"],"C",3,0,"b7e7ce2d04ec"],["While solving a radical equation, both sides of the equation are:",["Added","Subtracted","Squared","Divided"],"C",3,1,"25aacb4a93d2"],["A root obtained after squaring that does not satisfy the original radical equation is called:",["A rational root","An extraneous root","An equivalent root","A compound root"],"B",3,0,"bc0beafc94f5"],["What is the solution set of √(5x-4)= -14?",["{4}","{8}","{40}","φ (no solution)"],"D",3,0,"7b87b274fc0b"],["The absolute value of a real number x represents its distance from:",["1 on the number line","x on the number line","0 on the number line","−1 on the number line"],"C",3,0,"3d42cc5d7fb4"],["What is the solution set of |x| = 8?",["{8}","{−8}","{−8, 8}","φ"],"C",3,0,"97768792a9a1"],["What is the solution set of |x| = −6?",["{6}","{−6}","{−6, 6}","φ"],"D",3,0,"15b63513664e"],["What is the solution set of |x + 2| = 6?",["{4, −8}","{4, 8}","{−4, −8}","{−4, 8}"],"A",3,0,"fd37607b7138"],["If |x| = k where k < 0, then the solution set of the equation is:",["{k}","{−k, k}","{0}","φ"],"D",3,0,"6ec7a3f84a14"],["What is the solution set of |2x − 1| = 5?",["{−2, 3}","{2, −3}","{2, 3}","{−2, −3}"],"A",3,0,"ed80b739ef44"],["A statement that two algebraic expressions are not equal is called:",["An equation","An inequality","An identity","A radical"],"B",3,0,"75e3dc9f04b0"],["Which one of the following is a strict inequality?",["x + 3 ≠ 0","12x > 5","2y − 3 ≤ 0","4x + 5 ≥ 0"],"B",3,0,"f1a905ecf2e6"],["When both sides of an inequality are multiplied or divided by a negative number, the inequality symbol:",["Remains the same","Is reversed","Becomes an equality","Is removed"],"B",3,0,"8536c6d17448"],["What is the solution set of 8x + 9 < 6x − 7?",["{x | x ∈ R ∧ x < −8}","{x | x ∈ R ∧ x > −8}","{x | x ∈ R ∧ x < 8}","{x | x ∈ R ∧ x > 8}"],"A",3,0,"5486297e9c34"],["A compound inequality formed by joining two inequalities with the word “and” is true when:",["At least one inequality is true","Both inequalities are true","Exactly one inequality is true","Neither inequality is true"],"B",3,0,"904558db995c"],["For a compound inequality joined by “or”, the solution set is the:",["Union of both solution sets","Intersection of both solution sets","Difference of both solution sets","Product of both solution sets"],"A",3,0,"240c48f893b4"],["What is the solution set of the compound inequality x − 5 ≥ −1 and x + 3 ≤ 10, x ∈ R?",["{x | x ∈ R ∧ 4 ≤ x ≤ 7}","{x | x ∈ R ∧ x ≤ 7}","{x | x ∈ R ∧ x ≥ 4}","{x | x ∈ R ∧ x < 4}"],"A",3,0,"1c4fa394b052"],["If 5 ≥ 1 and 1 ≥ 1 are both true, then by the transitive property, which statement must also be true?",["5 ≤ 1","1 ≥ 5","5 ≥ 1","5 = 1"],"C",3,0,"15e3a0f0c940"],["The sum of five times a number x and 10 is less than −35. What inequality represents this statement?",["5x + 10 < −35","5x − 10 < −35","5(x + 10) < −35","5x + 10 > −35"],"A",3,0,"d70076d53488"],["What is the solution set of |x| = −3?",["{3}","{−3}","{−3, 3}","φ"],"D",3,0,"15b63513664e"],["An equation such as √(x + 1) = 4, where the variable is under a root sign, is a:",["linear equation","radical equation","absolute value equation","compound equation"],"B",3,0,"f47f1a8262a4"],["|x| measures the distance of x from:",["1","x","0","−1"],"C",1,0,"3d42cc5d7fb4"],["What is the solution set of 5x + 4 < 3x − 6?",["{x : x < −5}","{x : x > −5}","{x : x < 5}","{x : x > 5}"],"A",5,0,"5486297e9c34"],["A mathematical statement such as 2x + 1 > 7 is called:",["an equation","an inequality","an identity","a radical"],"B",1,0,"75e3dc9f04b0"],["What is the solution set of x − 2 ≥ 1 and x + 4 ≤ 12?",["{x : 3 ≤ x ≤ 8}","{x : x ≤ 8}","{x : x ≥ 3}","{x : −3 ≤ x ≤ 8}"],"A",5,0,"1c4fa394b052"],["The solution of 4x + 15 = −1 is:",["x = 3.5","x = 4","x = −16","x = −4"],"D",3,0,"gen-maths-m5-solve-linear"],["The solution of 5x − 7 = 13 is:",["x = −4","x = 1.2","x = 4","x = 20"],"C",3,0,"gen-maths-m5-solve-linear"],["The solution of 5x + 2 = 42 is:",["x = 40","x = 8.8","x = −8","x = 8"],"D",3,0,"gen-maths-m5-solve-linear"],["The solution of 2x − 7 = 11 is:",["x = 2","x = −9","x = 9","x = 18"],"C",3,0,"gen-maths-m5-solve-linear"],["The solution of 4x − 3 = 5 is:",["x = 2","x = 8","x = 0.5","x = −2"],"A",3,0,"gen-maths-m5-solve-linear"],["The solution of 4x + 7 = 27 is:",["x = 5","x = 20","x = 8.5","x = −5